static void test_range_based_replace() {
   std::string doc1 = "Before";
   doc1.push_back(phext::CHAPTER_BREAK);
   doc1 += "text to be replaced";
   doc1.push_back(phext::VOLUME_BREAK);
   doc1 += "also this";
   doc1.push_back(phext::COLLECTION_BREAK);
   doc1 += "and this";
   doc1.push_back(phext::SCROLL_BREAK);
   doc1 += "After";
   const phext::Range range1{C("1.1.1/1.1.1/2.1.1"), C("1.1.1/2.1.1/1.1.1")};
   std::string expected1 = "Before";
   expected1.push_back(phext::CHAPTER_BREAK);
   expected1.push_back(phext::SCROLL_BREAK);
   expected1 += "After";
   CHECK_EQ_STR(phext::range_replace(doc1, range1, ""), expected1);

   std::string doc2 = "Before";
   doc2.push_back(phext::LIBRARY_BREAK);
   doc2 += "Library two";
   doc2.push_back(phext::LIBRARY_BREAK);
   doc2 += "Library three";
   doc2.push_back(phext::LIBRARY_BREAK);
   doc2 += "Library four";
   const phext::Range range2{C("2.1.1/1.1.1/1.1.1"), C("3.1.1/1.1.1/1.1.1")};
   std::string expected2 = "Before";
   expected2.push_back(phext::LIBRARY_BREAK);
   expected2.push_back(phext::LIBRARY_BREAK);
   expected2 += "Library four";
   CHECK_EQ_STR(phext::range_replace(doc2, range2, ""), expected2);
}

static void test_next_scroll() {
   std::string doc1 = "3A";
   doc1.push_back(phext::SCROLL_BREAK);
   doc1 += "B2";
   doc1.push_back(phext::SECTION_BREAK);
   doc1 += "C1";
   const phext::NextScrollResult r = phext::next_scroll(doc1, C("1.1.1/1.1.1/1.1.1"));
   CHECK_EQ_STR(r.ps.coord.to_string(), "1.1.1/1.1.1/1.1.1");
   CHECK_EQ_STR(r.ps.scroll, "3A");
   CHECK_EQ_STR(r.next.to_string(), "1.1.1/1.1.1/1.1.2");
   std::string expected_remaining = "B2";
   expected_remaining.push_back(phext::SECTION_BREAK);
   expected_remaining += "C1";
   CHECK_EQ_STR(r.remaining, expected_remaining);
}

static void test_phokenize() {
   {
      std::string doc = "one";
      doc.push_back(phext::SCROLL_BREAK);
      doc += "two";
      doc.push_back(phext::SCROLL_BREAK);
      doc += "three";
      doc.push_back(phext::SCROLL_BREAK);
      doc += "four";
      const std::vector<phext::PositionedScroll> expected = {
          {C("1.1.1/1.1.1/1.1.1"), "one"}, {C("1.1.1/1.1.1/1.1.2"), "two"},
          {C("1.1.1/1.1.1/1.1.3"), "three"}, {C("1.1.1/1.1.1/1.1.4"), "four"}};
      CHECK(phext::phokenize(doc) == expected);
   }
   {
      std::string doc = "one";
      const char breaks[9] = {phext::LIBRARY_BREAK, phext::SHELF_BREAK, phext::SERIES_BREAK, phext::COLLECTION_BREAK,
                              phext::VOLUME_BREAK, phext::BOOK_BREAK, phext::CHAPTER_BREAK, phext::SECTION_BREAK, phext::SCROLL_BREAK};
      const char* words[9] = {"two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"};
      for (int i = 0; i < 9; ++i) {
         doc.push_back(breaks[i]);
         doc += words[i];
      }
      const std::vector<phext::PositionedScroll> expected = {
          {C("1.1.1/1.1.1/1.1.1"), "one"}, {C("2.1.1/1.1.1/1.1.1"), "two"}, {C("2.2.1/1.1.1/1.1.1"), "three"},
          {C("2.2.2/1.1.1/1.1.1"), "four"}, {C("2.2.2/2.1.1/1.1.1"), "five"}, {C("2.2.2/2.2.1/1.1.1"), "six"},
          {C("2.2.2/2.2.2/1.1.1"), "seven"}, {C("2.2.2/2.2.2/2.1.1"), "eight"}, {C("2.2.2/2.2.2/2.2.1"), "nine"},
          {C("2.2.2/2.2.2/2.2.2"), "ten"}};
      CHECK(phext::phokenize(doc) == expected);
   }
   {
      std::string doc = "one";
      const char breaks[9] = {phext::SCROLL_BREAK, phext::SECTION_BREAK, phext::CHAPTER_BREAK, phext::BOOK_BREAK,
                              phext::VOLUME_BREAK, phext::COLLECTION_BREAK, phext::SERIES_BREAK, phext::SHELF_BREAK,
                              phext::LIBRARY_BREAK};
      const char* words[9] = {"two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"};
      for (int i = 0; i < 9; ++i) {
         doc.push_back(breaks[i]);
         doc += words[i];
      }
      const std::vector<phext::PositionedScroll> expected = {
          {C("1.1.1/1.1.1/1.1.1"), "one"}, {C("1.1.1/1.1.1/1.1.2"), "two"}, {C("1.1.1/1.1.1/1.2.1"), "three"},
          {C("1.1.1/1.1.1/2.1.1"), "four"}, {C("1.1.1/1.1.2/1.1.1"), "five"}, {C("1.1.1/1.2.1/1.1.1"), "six"},
          {C("1.1.1/2.1.1/1.1.1"), "seven"}, {C("1.1.2/1.1.1/1.1.1"), "eight"}, {C("1.2.1/1.1.1/1.1.1"), "nine"},
          {C("2.1.1/1.1.1/1.1.1"), "ten"}};
      CHECK(phext::phokenize(doc) == expected);
   }
   {
      std::string doc;
      doc.push_back(phext::BOOK_BREAK);
      doc.push_back(phext::VOLUME_BREAK);
      doc.push_back(phext::COLLECTION_BREAK);
      doc.push_back(phext::SERIES_BREAK);
      doc.push_back(phext::SHELF_BREAK);
      doc.push_back(phext::LIBRARY_BREAK);
      doc += "stuff here";
      const std::vector<phext::PositionedScroll> expected = {{C("2.1.1/1.1.1/1.1.1"), "stuff here"}};
      CHECK(phext::phokenize(doc) == expected);
   }
}

