static void test_fs_read_write() {
   // RS writes unit-test.phext itself, then replaces within it. The vendored
   // tests/unit-test.phext holds exactly that content (SHA-256 checked by
   // scripts/run-tests.sh); this port verifies the fixture, then performs
   // the same replace the RS test performs.
   const std::string initial = "a simple phext doc with three scrolls\x17we just want to verify\x17that all of our breaks are making it through rust's fs layer.\x18section 2\x19" "chapter 2\x1A" "book 2\x1Cvolume 2\x1D" "collection 2\x1Eseries 2\x1Fshelf 2\x01library 2";
   const std::string prior = read_file("tests/unit-test.phext");
   CHECK_EQ_STR(prior, initial);
   const std::string message = phext::replace(prior, C("2.1.1/1.1.1/1.1.1"), "still lib 2");
   CHECK_EQ_STR(message, "a simple phext doc with three scrolls\x17we just want to verify\x17that all of our breaks are making it through rust's fs layer.\x18section 2\x19" "chapter 2\x1A" "book 2\x1Cvolume 2\x1D" "collection 2\x1Eseries 2\x1Fshelf 2\x01still lib 2");
}

